async function main() {
  console.log("Seeding prayer types...");

  for (const prayer of prayers) {
    await prisma.prayerType.upsert({
      where: { slug: prayer.slug },
      update: prayer,
      create: prayer,
    });
    console.log(`  + ${prayer.name}`);
  }

  console.log(`\nSeeded ${prayers.length} prayers successfully!`);
}

main()
  .then(() => prisma.$disconnect())
  .catch((e) => {
    console.error(e);
    prisma.$disconnect();
    process.exit(1);
  });
